<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/csrf.php';require_role(['Super Admin']);
$user=current_user();$error=$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='delete'){ $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id&&(int)$id!==$user['id']){$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);audit_log($pdo,(int)$user['id'],'Super Admin','Deleted user',$id);$success='User deleted.';}}
 elseif($action==='update'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$name=trim($_POST['name']??'');$role=$_POST['role']??'';$status=$_POST['status']??'';$allowed=['Student','Faculty','HOD','Principal','Super Admin'];if($id&&$name&&in_array($role,$allowed,true)&&in_array($status,['Active','Inactive','Locked'],true)){$pdo->prepare('UPDATE users SET name=?,role=?,status=? WHERE id=?')->execute([$name,$role,$status,$id]);audit_log($pdo,(int)$user['id'],'Super Admin','Updated user',$id);$success='User updated.';}else{$error='Invalid user values.';}}
 else{$name=trim($_POST['name']??'');$identifier=strtoupper(trim($_POST['identifier']??''));$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'';$password=$_POST['password']??'';$allowed=['Student','Faculty','HOD','Principal','Super Admin'];if($name===''||$identifier===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($role,$allowed,true)){$error='Complete all fields with a valid email and 8-character password.';}else{try{$pdo->prepare('INSERT INTO users(name,identifier,email,password_hash,role,status) VALUES(?,?,?,?,?,\'Active\')')->execute([$name,$identifier,$email,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)$pdo->lastInsertId();if($role==='Student'){$department=filter_input(INPUT_POST,'department_id',FILTER_VALIDATE_INT);$semester=filter_input(INPUT_POST,'semester',FILTER_VALIDATE_INT);if($department&&$semester){$pdo->prepare('INSERT INTO students(user_id,usn,department_id,semester) VALUES(?,?,?,?)')->execute([$id,$identifier,$department,$semester]);}}if($role==='Faculty'||$role==='HOD'){$department=filter_input(INPUT_POST,'department_id',FILTER_VALIDATE_INT);if($department){$pdo->prepare('INSERT INTO faculty(user_id,employee_id,department_id,designation) VALUES(?,?,?,?)')->execute([$id,$identifier,$department,'Faculty']);if($role==='HOD'){$pdo->prepare('UPDATE departments SET hod_user_id=? WHERE id=?')->execute([$id,$department]);}}}audit_log($pdo,(int)$user['id'],'Super Admin','Created user',$id);$success='User created.';}catch(PDOException $e){$error='Identifier or email already exists.';}}}
}
$users=$pdo->query('SELECT u.*,d.name department_name FROM users u LEFT JOIN students s ON s.user_id=u.id LEFT JOIN departments d ON d.id=s.department_id ORDER BY u.created_at DESC')->fetchAll();
$departments=$pdo->query('SELECT id,name FROM departments WHERE active=1 ORDER BY name')->fetchAll();
$pageTitle='Manage Users | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Super Admin</span></div><div class="avatar">SA</div></header><div class="content"><div class="page-header"><div><p>USER MANAGEMENT</p><h1>Users</h1></div></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?>
<section class="panel form-panel"><details><summary class="action-btn">Add New User</summary><form method="post" class="auth-form" style="width:100%;margin-top:12px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="form-grid"><label>Name<input name="name" required></label><label>Identifier<input name="identifier" required></label></div><div class="form-grid"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label></div><div class="form-grid"><label>Role<select name="role"><option>Student</option><option>Faculty</option><option>HOD</option><option>Principal</option><option>Super Admin</option></select></label><label>Department<select name="department_id"><option value="">None</option><?php foreach($departments as $d):?><option value="<?=(int)$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></label></div><label>Semester for student<select name="semester"><?php for($i=1;$i<=8;$i++):?><option value="<?=$i?>"><?=$i?></option><?php endfor;?></select></label><button class="btn btn-primary" type="submit">Create User</button></form></details></section>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Identifier</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['identifier'])?></td><td><?=e($r['role'])?></td><td><b class="status <?=$r['status']==='Active'?'approved':'rejected'?>"><?=e($r['status'])?></b></td><td><details><summary class="action-btn">Edit</summary><form method="post" class="inline-form" style="display:grid;margin-top:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="name" value="<?=e($r['name'])?>" required><select name="role"><?php foreach(['Student','Faculty','HOD','Principal','Super Admin'] as $role):?><option <?=$role===$r['role']?'selected':''?>><?=$role?></option><?php endforeach;?></select><select name="status"><?php foreach(['Active','Inactive','Locked'] as $status):?><option <?=$status===$r['status']?'selected':''?>><?=$status?></option><?php endforeach;?></select><button class="action-btn approve" type="submit">Save</button></form></details><?php if((int)$r['id']!==$user['id']):?><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="action-btn reject" type="submit" onclick="return confirm('Delete this user?')">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
